-- Derived lexical terms are expression indexes, not portable product records.
-- SQLite maintains them on every source change and erasure; reads write nothing.
CREATE INDEX penny_suggestions_operator ON requests(merged_into_request_id,(CASE WHEN (coalesce(title,'null')||char(10)||coalesce(description,'null')) GLOB ('*[^'||char(9)||char(10)||char(13)||' -~]*') THEN NULL ELSE ' '||lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(title,'null')||char(10)||coalesce(description,'null'),char(9),' '),char(10),' '),char(13),' '),char(33),' '),char(34),' '),char(35),' '),char(36),' '),char(37),' '),char(38),' '),char(39),' '),char(40),' '),char(41),' '),char(42),' '),char(43),' '),char(44),' '),char(45),' '),char(46),' '),char(47),' '),char(58),' '),char(59),' '),char(60),' '),char(61),' '),char(62),' '),char(63),' '),char(64),' '),char(91),' '),char(92),' '),char(93),' '),char(94),' '),char(95),' '),char(96),' '),char(123),' '),char(124),' '),char(125),' '),char(126),' '))||' ' END),id,slug,board_id);
