CREATE INDEX penny_suggestions_blocked ON requesters(id,blocked_at) WHERE blocked_at IS NOT NULL;

-- Read-only views keep the indexed expression behind a native SELECT door.
CREATE VIEW penny_suggestions_operator_rows AS SELECT id,slug,board_id,merged_into_request_id,(CASE WHEN (coalesce(title,'null')||char(10)||coalesce(description,'null')) GLOB ('*[^'||char(9)||char(10)||char(13)||' -~]*') THEN NULL ELSE ' '||lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(title,'null')||char(10)||coalesce(description,'null'),char(9),' '),char(10),' '),char(13),' '),char(33),' '),char(34),' '),char(35),' '),char(36),' '),char(37),' '),char(38),' '),char(39),' '),char(40),' '),char(41),' '),char(42),' '),char(43),' '),char(44),' '),char(45),' '),char(46),' '),char(47),' '),char(58),' '),char(59),' '),char(60),' '),char(61),' '),char(62),' '),char(63),' '),char(64),' '),char(91),' '),char(92),' '),char(93),' '),char(94),' '),char(95),' '),char(96),' '),char(123),' '),char(124),' '),char(125),' '),char(126),' '))||' ' END) AS terms FROM requests INDEXED BY penny_suggestions_operator;
CREATE VIEW penny_suggestions_public_rows AS SELECT id,slug,board_id,author_requester_id,merged_into_request_id,moderation_state,public_state,published_at,withdrawn_at,(CASE WHEN (coalesce(public_title,'null')||char(10)||coalesce(public_description,'null')) GLOB ('*[^'||char(9)||char(10)||char(13)||' -~]*') THEN NULL ELSE ' '||lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce(public_title,'null')||char(10)||coalesce(public_description,'null'),char(9),' '),char(10),' '),char(13),' '),char(33),' '),char(34),' '),char(35),' '),char(36),' '),char(37),' '),char(38),' '),char(39),' '),char(40),' '),char(41),' '),char(42),' '),char(43),' '),char(44),' '),char(45),' '),char(46),' '),char(47),' '),char(58),' '),char(59),' '),char(60),' '),char(61),' '),char(62),' '),char(63),' '),char(64),' '),char(91),' '),char(92),' '),char(93),' '),char(94),' '),char(95),' '),char(96),' '),char(123),' '),char(124),' '),char(125),' '),char(126),' '))||' ' END) AS terms FROM requests INDEXED BY penny_suggestions_public;
